const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const normalize=q=>String(q||'').normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim();
function validate(data){const ids=new Set();for(const p of data.papers){if(ids.has(p.id))throw Error('Duplicate paper identity: '+p.id);ids.add(p.id);if(!p.directionIds.length||!p.directionIds.every(id=>data.directions.some(d=>d.id===id)))throw Error('Unknown direction');}for(const e of data.lineage||[])if(!e.provenance||!e.sourceUrl||!e.locator)throw Error('Research lineage requires source and locator');return data;}
